Create src/engine/EngineRegistry.ts with the EngineRegistry class and normalizeCardSide helper.

Implement:
```typescript
import type { RenderEngine, CardSide } from '@/types';

class EngineRegistry {
  private engines = new Map<string, RenderEngine>()

  register(id: string, engine: RenderEngine): void {
    this.engines.set(id, engine)
  }

  resolve(id?: string): RenderEngine {
    if (!id || !this.engines.has(id)) {
      // Fallback: return TextEngine if registered, or a minimal text renderer
      const fallback = this.engines.get('text')
      if (fallback) return fallback
      // Minimal fallback if text engine not yet registered
      return {
        render(data: any, target: HTMLElement) {
          target.textContent = String(data ?? '')
        }
      }
    }
    return this.engines.get(id)!
  }
}

function normalizeCardSide(side: CardSide): { data: any; renderEngineId: string } {
  if (typeof side === 'string') return { data: side, renderEngineId: 'text' }
  return side
}

// Singleton instance
const engineRegistry = new EngineRegistry()

export { EngineRegistry, normalizeCardSide, engineRegistry }
export type { RenderEngine }
```

Rules:
- resolve() never throws — always returns a valid engine
- Falls back to TextEngine (id='text') for unknown or missing IDs
- normalizeCardSide converts plain string → { data, renderEngineId: 'text' }
- Export a singleton instance `engineRegistry` for use across the app

Reference: apps/flashcards/docs/how/sprints/sprint-1-render-engine/sprint.md — sections 2 and 3

Create src/engine/TextEngine.ts implementing the RenderEngine interface for plain text rendering.

Implement:
```typescript
import type { RenderEngine } from '@/types';

const TextEngine: RenderEngine = {
  render(data: any, target: HTMLElement): void {
    target.textContent = String(data ?? '')
  }
}

export { TextEngine }
```

Rules:
- render() is synchronous — sets target.textContent directly
- No precompute implementation — flip is always instant
- Engine must be pure — no side effects beyond target DOM
- Handle null/undefined data gracefully (render as empty string)

